import{_ as a,c as n,o as e,ag as r}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Knappar och indikatorer","description":"","frontmatter":{},"headers":[],"relativePath":"07-hmi-design/knappar-indikatorer.md","filePath":"07-hmi-design/knappar-indikatorer.md","lastUpdated":1768472766000}'),s={name:"07-hmi-design/knappar-indikatorer.md"};function i(o,t,l,p,d,g){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="knappar-och-indikatorer" tabindex="-1">Knappar och indikatorer <a class="header-anchor" href="#knappar-och-indikatorer" aria-label="Permalink to &quot;Knappar och indikatorer&quot;">​</a></h1><p>Knappar och indikatorer är <strong>kärnan</strong> i HMI-interaktionen - de låter operatörer styra processen och få omedelbar feedback. Detta avsnitt täcker hur du skapar och konfigurerar interaktiva element i WinCC.</p><h2 id="knappar-buttons" tabindex="-1">Knappar (Buttons) <a class="header-anchor" href="#knappar-buttons" aria-label="Permalink to &quot;Knappar (Buttons)&quot;">​</a></h2><h3 id="lagga-till-knapp" tabindex="-1">Lägga till knapp <a class="header-anchor" href="#lagga-till-knapp" aria-label="Permalink to &quot;Lägga till knapp&quot;">​</a></h3><ol><li><strong>Öppna skärm</strong> i WinCC-editorn</li><li>Från <strong>Toolbox</strong> (höger sida): Dra <strong>Button</strong> till skärmen</li><li>Dubbelklicka för att redigera text: &quot;START&quot;</li></ol><h3 id="knapp-typer" tabindex="-1">Knapp-typer <a class="header-anchor" href="#knapp-typer" aria-label="Permalink to &quot;Knapp-typer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Typ</th><th>Beteende</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Momentary</strong></td><td>Aktiv när hålls nere</td><td>Start-knappar, jogg-funktioner</td></tr><tr><td><strong>Toggle</strong></td><td>On/Off varje klick</td><td>Lampkontakter, låsningar</td></tr><tr><td><strong>Two-state</strong></td><td>Följer tagg-värde</td><td>Visa motor-status (igång/stopp)</td></tr></tbody></table><h3 id="konfigurera-knapp-events" tabindex="-1">Konfigurera knapp-events <a class="header-anchor" href="#konfigurera-knapp-events" aria-label="Permalink to &quot;Konfigurera knapp-events&quot;">​</a></h3><p><strong>Event-typer:</strong></p><h4 id="_1-click-klick" tabindex="-1">1. Click (Klick) <a class="header-anchor" href="#_1-click-klick" aria-label="Permalink to &quot;1. Click (Klick)&quot;">​</a></h4><p>Enklaste eventet - kör funktion vid klick.</p><p><strong>Exempel: Start motor</strong></p><ol><li>Markera knappen → <strong>Properties</strong> → <strong>Events</strong></li><li>Klicka <strong>[+]</strong> vid <strong>Click</strong></li><li><strong>Function:</strong> SetBit</li><li><strong>Tag:</strong> <code>Motor_Start</code></li></ol><p><strong>Resultat:</strong> När knapp klickas, sätts <code>Motor_Start := TRUE</code></p><h4 id="_2-press-nedtryckning" tabindex="-1">2. Press (Nedtryckning) <a class="header-anchor" href="#_2-press-nedtryckning" aria-label="Permalink to &quot;2. Press (Nedtryckning)&quot;">​</a></h4><p>Aktiveras när knapp <strong>trycks ner</strong> (innan släppt).</p><p><strong>Användning:</strong> Jogg-funktion, manuell matning.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Press: SetBit &quot;Conveyor_Forward&quot;</span></span>
<span class="line"><span>Release: ResetBit &quot;Conveyor_Forward&quot;</span></span></code></pre></div><h3 id="vanliga-knapp-funktioner" tabindex="-1">Vanliga knapp-funktioner <a class="header-anchor" href="#vanliga-knapp-funktioner" aria-label="Permalink to &quot;Vanliga knapp-funktioner&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Funktion</th><th>Beskrivning</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>SetBit</strong></td><td>Sätt tagg till TRUE</td><td>Start motor</td></tr><tr><td><strong>ResetBit</strong></td><td>Sätt tagg till FALSE</td><td>Stopp motor</td></tr><tr><td><strong>InvertBit</strong></td><td>Växla TRUE/FALSE</td><td>Toggle lampa</td></tr><tr><td><strong>SetValue</strong></td><td>Skriv värde till tagg</td><td>Sätt hastighet</td></tr><tr><td><strong>IncrementValue</strong></td><td>Öka värde</td><td>Räknare++</td></tr><tr><td><strong>DecrementValue</strong></td><td>Minska värde</td><td>Räknare--</td></tr><tr><td><strong>ActivateScreen</strong></td><td>Byt skärm</td><td>Navigation</td></tr><tr><td><strong>ShowPopupScreen</strong></td><td>Öppna popup</td><td>Dialog</td></tr></tbody></table><h3 id="exempel-start-stop-knappar" tabindex="-1">Exempel: START/STOP-knappar <a class="header-anchor" href="#exempel-start-stop-knappar" aria-label="Permalink to &quot;Exempel: START/STOP-knappar&quot;">​</a></h3><p><strong>START-knapp:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Text: &quot;▶ START&quot;</span></span>
<span class="line"><span>Event: Click</span></span>
<span class="line"><span>Function: SetBit</span></span>
<span class="line"><span>Tag: Motor_M01_Start</span></span>
<span class="line"><span>Background: Grön (#00FF00)</span></span></code></pre></div><p><strong>STOP-knapp:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Text: &quot;⏹ STOP&quot;</span></span>
<span class="line"><span>Event: Click</span></span>
<span class="line"><span>Function: ResetBit</span></span>
<span class="line"><span>Tag: Motor_M01_Start</span></span>
<span class="line"><span>Background: Röd (#FF0000)</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Säkerhet</p><p>Använd alltid bekräftelse för:</p><ul><li>Nödstopp</li><li>Reset av säkerhetsfunktioner</li><li>Radering av data</li><li>Batch-avbrott</li></ul></div><h2 id="indikatorer" tabindex="-1">Indikatorer <a class="header-anchor" href="#indikatorer" aria-label="Permalink to &quot;Indikatorer&quot;">​</a></h2><h3 id="circle-cirkel-indikator" tabindex="-1">Circle (Cirkel-indikator) <a class="header-anchor" href="#circle-cirkel-indikator" aria-label="Permalink to &quot;Circle (Cirkel-indikator)&quot;">​</a></h3><p>Enklaste indikatorn - visar on/off-status med färg.</p><p><strong>Användning:</strong> Lampor, motor-status, ventilpositioner.</p><p><strong>Skapa cirkel-indikator:</strong></p><ol><li>Toolbox → <strong>Basic objects</strong> → <strong>Circle</strong></li><li>Rita cirkel (50x50 px)</li><li><strong>Properties</strong> → <strong>Animations</strong></li><li>Klicka <strong>[+]</strong> vid <strong>Appearance</strong></li><li><strong>Type:</strong> Visibility eller Background color</li><li><strong>Tag:</strong> <code>Motor_Running</code></li><li><strong>Range:</strong><ul><li>TRUE: Grön (#00FF00)</li><li>FALSE: Grå (#808080)</li></ul></li></ol><h3 id="text-indikatorer" tabindex="-1">Text-indikatorer <a class="header-anchor" href="#text-indikatorer" aria-label="Permalink to &quot;Text-indikatorer&quot;">​</a></h3><p>Visa status med text istället för färg.</p><p><strong>Exempel:</strong></p><ol><li>Lägg till <strong>Text field</strong></li><li><strong>Properties</strong> → <strong>Text list</strong></li><li>Koppla till <code>Motor_Status</code> (INT)</li><li><strong>Text list:</strong><ul><li>0: &quot;Stopped&quot;</li><li>1: &quot;Starting&quot;</li><li>2: &quot;Running&quot;</li><li>3: &quot;Stopping&quot;</li><li>4: &quot;Fault&quot;</li></ul></li></ol><h2 id="i-o-fields-in-utmatningsfalt" tabindex="-1">I/O Fields (In-/utmatningsfält) <a class="header-anchor" href="#i-o-fields-in-utmatningsfalt" aria-label="Permalink to &quot;I/O Fields (In-/utmatningsfält)&quot;">​</a></h2><h3 id="read-only-field-visa-varde" tabindex="-1">Read-only field (visa värde) <a class="header-anchor" href="#read-only-field-visa-varde" aria-label="Permalink to &quot;Read-only field (visa värde)&quot;">​</a></h3><p>Visa realtidsvärden från PLC.</p><p><strong>Exempel: Visa motorhastighet</strong></p><ol><li>Toolbox → <strong>I/O field</strong></li><li>Placera på skärmen</li><li><strong>Properties</strong> → <strong>General</strong></li><li><strong>Tag:</strong> <code>Motor_Speed</code> (INT)</li><li><strong>Mode:</strong> Input/Output (men HMI-tag är Read-only)</li><li><strong>Format:</strong> &quot;0000 rpm&quot;</li></ol><h3 id="input-field-skriv-varde" tabindex="-1">Input field (skriv värde) <a class="header-anchor" href="#input-field-skriv-varde" aria-label="Permalink to &quot;Input field (skriv värde)&quot;">​</a></h3><p>Låt operatör skriva värde.</p><p><strong>Exempel: Hastighetsinställning</strong></p><ol><li>I/O field</li><li><strong>Tag:</strong> <code>Motor_Speed_Setpoint</code></li><li><strong>Mode:</strong> Input/Output</li><li><strong>Keyboard:</strong> Numeric (vid klick visas numeriskt tangentbord)</li><li><strong>Limits:</strong> Min: 0, Max: 1500</li></ol><div class="tip custom-block"><p class="custom-block-title">Input-validering</p><p>Använd <strong>Limits</strong> för att förhindra ogiltiga värden. HMI varnar om värde utanför tillåtet område.</p></div><h3 id="format-och-enheter" tabindex="-1">Format och enheter <a class="header-anchor" href="#format-och-enheter" aria-label="Permalink to &quot;Format och enheter&quot;">​</a></h3><p><strong>Format-strängar:</strong></p><table tabindex="0"><thead><tr><th>Format</th><th>Exempel-värde</th><th>Visning</th></tr></thead><tbody><tr><td><code>0000</code></td><td>125</td><td><code>0125</code></td></tr><tr><td><code>####</code></td><td>125</td><td><code>125</code></td></tr><tr><td><code>0.00</code></td><td>12.5</td><td><code>12.50</code></td></tr><tr><td><code>#.#</code></td><td>12.5</td><td><code>12.5</code></td></tr></tbody></table><p><strong>Enheter:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Format: &quot;0.0 °C&quot;    → 25.5 °C</span></span>
<span class="line"><span>Format: &quot;#### rpm&quot;  → 1450 rpm</span></span>
<span class="line"><span>Format: &quot;#.## bar&quot; → 5.75 bar</span></span></code></pre></div><h2 id="sliders-skjutreglage" tabindex="-1">Sliders (Skjutreglage) <a class="header-anchor" href="#sliders-skjutreglage" aria-label="Permalink to &quot;Sliders (Skjutreglage)&quot;">​</a></h2><p>För enkel justering av värden.</p><h3 id="skapa-slider" tabindex="-1">Skapa slider <a class="header-anchor" href="#skapa-slider" aria-label="Permalink to &quot;Skapa slider&quot;">​</a></h3><ol><li>Toolbox → <strong>Slider</strong></li><li>Placera på skärmen (horisontell eller vertikal)</li><li><strong>Properties:</strong><ul><li><strong>Tag:</strong> <code>Motor_Speed_Setpoint</code></li><li><strong>Min value:</strong> 0</li><li><strong>Max value:</strong> 1500</li><li><strong>Orientation:</strong> Horizontal</li></ul></li></ol><p><strong>Resultat:</strong> Operatör drar slider → <code>Motor_Speed_Setpoint</code> uppdateras (0-1500).</p><h2 id="gauges-matare" tabindex="-1">Gauges (Mätare) <a class="header-anchor" href="#gauges-matare" aria-label="Permalink to &quot;Gauges (Mätare)&quot;">​</a></h2><p>Visuella mätare för analoga värden.</p><h3 id="typer-av-gauges" tabindex="-1">Typer av gauges <a class="header-anchor" href="#typer-av-gauges" aria-label="Permalink to &quot;Typer av gauges&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Typ</th><th>Stil</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Bar gauge</strong></td><td>Horisontell/vertikal balk</td><td>Tanknivå, tryck</td></tr><tr><td><strong>Circular gauge</strong></td><td>Cirkulär mätare (hastighetsmätare)</td><td>Hastighet, temperatur</td></tr></tbody></table><h3 id="skapa-bar-gauge" tabindex="-1">Skapa bar gauge <a class="header-anchor" href="#skapa-bar-gauge" aria-label="Permalink to &quot;Skapa bar gauge&quot;">​</a></h3><ol><li>Toolbox → <strong>Gauges</strong> → <strong>Bar</strong></li><li><strong>Properties:</strong><ul><li><strong>Tag:</strong> <code>Tank_Level</code> (REAL)</li><li><strong>Min value:</strong> 0.0</li><li><strong>Max value:</strong> 100.0</li><li><strong>Orientation:</strong> Vertical</li></ul></li><li><strong>Appearance:</strong><ul><li><strong>Color ranges:</strong><ul><li>0-20: Röd (låg nivå)</li><li>20-80: Grön (normal)</li><li>80-100: Gul (hög nivå)</li></ul></li></ul></li></ol><h2 id="lampor-och-blinkande-indikatorer" tabindex="-1">Lampor och blinkande indikatorer <a class="header-anchor" href="#lampor-och-blinkande-indikatorer" aria-label="Permalink to &quot;Lampor och blinkande indikatorer&quot;">​</a></h2><h3 id="enkel-lampa" tabindex="-1">Enkel lampa <a class="header-anchor" href="#enkel-lampa" aria-label="Permalink to &quot;Enkel lampa&quot;">​</a></h3><p><strong>Circle med animation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Circle (30x30 px)</span></span>
<span class="line"><span>Animation: Background color</span></span>
<span class="line"><span>  Tag: Alarm_Active</span></span>
<span class="line"><span>  TRUE: Röd (#FF0000)</span></span>
<span class="line"><span>  FALSE: Grå (#404040)</span></span></code></pre></div><h3 id="blinkande-larm" tabindex="-1">Blinkande larm <a class="header-anchor" href="#blinkande-larm" aria-label="Permalink to &quot;Blinkande larm&quot;">​</a></h3><p>För kritiska larm, använd blinkande animation.</p><p><strong>Metod 1: WinCC blink-funktion</strong></p><ol><li>Circle → <strong>Animations</strong> → <strong>Appearance</strong></li><li><strong>Blink:</strong> Enable</li><li><strong>Blink frequency:</strong> 2 Hz (2 blinkningar/sekund)</li><li><strong>Tag:</strong> <code>Alarm_Critical</code></li></ol><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Designrekommendationer</p><p><strong>Knappar:</strong></p><ol><li><strong>Storlek:</strong> Minst 50x50 px för touch-paneler (fingerstorlek)</li><li><strong>Avstånd:</strong> 10 px mellan knappar för att undvika felklick</li><li><strong>Färgkodning:</strong><ul><li>🟢 Grön: START, OK, Aktivera</li><li>🔴 Röd: STOP, Fel, Nöd</li><li>🟡 Gul: Varning, Paus</li><li>🔵 Blå: Information, Navigation</li></ul></li><li><strong>Etiketter:</strong> Tydliga, korta (max 10 tecken)</li><li><strong>Feedback:</strong> Knapp ska ändra utseende vid klick</li></ol><p><strong>Indikatorer:</strong></p><ol><li><strong>Konsistens:</strong> Samma färger överallt (grön = ok, röd = fel)</li><li><strong>Gruppering:</strong> Placera relaterade indikatorer nära varandra</li><li><strong>Läsbarhet:</strong> Stor text (min 12 pt) för värden</li><li><strong>Enheter:</strong> Visa alltid enhet (rpm, °C, bar, %)</li><li><strong>Uppdateringsfrekvens:</strong> 100 ms för realtid, 500 ms för långsamma värden</li></ol></div><h2 id="exempel-motorstyrningspanel" tabindex="-1">Exempel: Motorstyrningspanel <a class="header-anchor" href="#exempel-motorstyrningspanel" aria-label="Permalink to &quot;Exempel: Motorstyrningspanel&quot;">​</a></h2><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────┐</span></span>
<span class="line"><span>│  Motor M01                       │</span></span>
<span class="line"><span>├──────────────────────────────────┤</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  🟢 Running     🔴 Fault        │  ← Cirkel-indikatorer</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  Speed:    [1450] rpm            │  ← I/O field (read-only)</span></span>
<span class="line"><span>│  Current:  [12.5] A              │</span></span>
<span class="line"><span>│  Temp:     [65] °C               │</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  [▶ START]      [⏹ STOP]        │  ← Knappar</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  Setpoint: [____] rpm            │  ← I/O field (input)</span></span>
<span class="line"><span>│  [===|=========] 0-1500          │  ← Slider</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  Speed: [████████░░] 60%         │  ← Bar gauge</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>└──────────────────────────────────┘</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=wincc%20controls%20buttons%20indicators" target="_blank" rel="noreferrer">Siemens: WinCC Controls dokumentation (sökresultat)</a></li><li><a href="https://www.youtube.com/watch?v=dKl5Z6kJ9tU" target="_blank" rel="noreferrer">Video: Creating Buttons and Indicators</a></li><li><a href="https://www.youtube.com/watch?v=Xy-8FcN4p9g" target="_blank" rel="noreferrer">Video: I/O Fields and Data Entry</a></li><li><a href="./dynamiska-objekt.html">Nästa: Dynamiska objekt →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./skarmbilder.html">Skärmbilder och layout</a></li><li><a href="./dynamiska-objekt.html">Dynamiska objekt och animationer</a></li><li><a href="./../05-taggar/koppling-plc-hmi.html">Koppling PLC↔HMI</a></li></ul>`,80)])])}const k=a(s,[["render",i]]);export{h as __pageData,k as default};
